CREATE TABLE lock_pk_reverse (a INT NOT NULL,b INT NOT NULL,PRIMARY KEY(b,a)) ENGINE=InnoDB;
CREATE TABLE lock_tiny_keys (id TINYINT(1) NOT NULL,PRIMARY KEY(id)) ENGINE=InnoDB;
CREATE TABLE lock_decimal_keys (id DECIMAL(30,20) NOT NULL,PRIMARY KEY(id)) ENGINE=InnoDB;
CREATE TABLE lock_binary_keys (id VARBINARY(8) NOT NULL,PRIMARY KEY(id)) ENGINE=InnoDB;
CREATE TABLE lock_hash_collision (AaAaAaAa INT NOT NULL,AaAaAaBB INT NOT NULL,AaAaBBAa INT NOT NULL,AaAaBBBB INT NOT NULL,AaBBAaAa INT NOT NULL,AaBBAaBB INT NOT NULL,AaBBBBAa INT NOT NULL,AaBBBBBB INT NOT NULL,BBAaAaAa INT NOT NULL,BBAaAaBB INT NOT NULL,BBAaBBAa INT NOT NULL,BBAaBBBB INT NOT NULL,BBBBAaAa INT NOT NULL,BBBBAaBB INT NOT NULL,BBBBBBAa INT NOT NULL,BBBBBBBB INT NOT NULL,PRIMARY KEY(BBBBBBBB,BBBBBBAa,BBBBAaBB,BBBBAaAa,BBAaBBBB,BBAaBBAa,BBAaAaBB,BBAaAaAa,AaBBBBBB,AaBBBBAa,AaBBAaBB,AaBBAaAa,AaAaBBBB,AaAaBBAa,AaAaAaBB,AaAaAaAa)) ENGINE=InnoDB;
